package com.grandsigil.config;

import net.minecraftforge.common.ForgeConfigSpec;
import org.apache.commons.lang3.tuple.Pair;

public final class GsConfig {
    public static final Common COMMON;
    public static final ForgeConfigSpec COMMON_SPEC;
    public static final Client CLIENT;
    public static final ForgeConfigSpec CLIENT_SPEC;

    private GsConfig() {
    }

    static {
        Pair common = new ForgeConfigSpec.Builder().configure(Common::new);
        COMMON = (Common)common.getLeft();
        COMMON_SPEC = (ForgeConfigSpec)common.getRight();
        Pair client = new ForgeConfigSpec.Builder().configure(Client::new);
        CLIENT = (Client)client.getLeft();
        CLIENT_SPEC = (ForgeConfigSpec)client.getRight();
    }

    public static final class Common {
        public final ForgeConfigSpec.DoubleValue damageMultiplier;
        public final ForgeConfigSpec.IntValue chargeSeconds;
        public final ForgeConfigSpec.BooleanValue sigilBinds;
        public final ForgeConfigSpec.BooleanValue scorchesGround;
        public final ForgeConfigSpec.IntValue maxTargets;
        public final ForgeConfigSpec.BooleanValue onePerBook;
        public final ForgeConfigSpec.BooleanValue gazeHolds;
        public final ForgeConfigSpec.BooleanValue fieldsPave;
        public final ForgeConfigSpec.BooleanValue coffinHolds;

        Common(ForgeConfigSpec.Builder builder) {
            builder.comment("Every spell in this mod").push("general");
            this.damageMultiplier = builder.comment("Scales everything these spells deal.").defineInRange("damageMultiplier", 1.0, 0.0, 10.0);
            this.maxTargets = builder.comment("Hard cap on how many things one casting may hit.").defineInRange("maxTargets", 64, 1, 512);
            this.onePerBook = builder.comment(new String[]{"A spell book may hold only one Apex Arcana ultimate (Iron's own spells are never", "limited). Turn this off to let a book carry as many as it has slots. There is also", "a gamerule, /gamerule grandsigilOnePerBook, so it can be changed per world in game;", "the limit applies only while both this and the gamerule are on."}).define("onePerBook", true);
            builder.pop();
            builder.comment("Grand Sigil").push("sigil");
            this.chargeSeconds = builder.comment(new String[]{"How long the ritual takes, from the circle being drawn to the", "column landing. The twelve runes light across the first five", "sevenths of it; the wind-up is the rest."}).defineInRange("chargeSeconds", 7, 3, 120);
            this.sigilBinds = builder.comment(new String[]{"Whether the circle holds the creature it was drawn under.", "This is the spell: turn it off and the ritual still runs and the", "column still lands, but the target can walk out of the ring -- which", "ends it, because the circle only ever hits that one thing."}).define("binds", true);
            this.scorchesGround = builder.comment(new String[]{"Whether the column of light leaves a ring of fire when it fires.", "Off by default: this is the only thing the spell does to the world."}).define("scorchesGround", false);
            builder.pop();
            builder.comment("The Gaze").push("gaze");
            this.gazeHolds = builder.comment(new String[]{"Whether being watched stops you moving and casting.", "This is the spell: turn it off and the eye still opens and", "still burns everything under it, but nothing is held. Worth", "turning off on a PvP server that would rather not have a", "fourteen-second lockdown in it."}).define("holds", true);
            builder.pop();
            builder.comment("Black Coffin").push("coffin");
            this.coffinHolds = builder.comment(new String[]{"Whether being shut in the box stops you walking out of it.", "This is the spell: the lances are four seconds long and they only", "land on something that is still there. Turn it off and the box", "still closes and still drives its lances, but anything quick", "enough can leave through the wall. Spells are never taken away --", "being sealed in a box with four seconds to answer it is a better", "fight than being sealed in a box."}).define("holds", true);
            builder.pop();
            builder.comment("The nine domains").push("fields");
            this.fieldsPave = builder.comment(new String[]{"Whether a domain repaves the ground inside it.", "This is what the nine field spells are: the buff and the debuff are", "one piece of terrain read from two sides. Turn it off and they still", "hold and still favour their caster, but the floor does not change.", "Nothing is ever destroyed either way -- every block is written down", "with what was under it and put back when the domain ends."}).define("pave", true);
            builder.pop();
        }
    }

    public static final class Client {
        public final ForgeConfigSpec.BooleanValue screenDistortion;
        public final ForgeConfigSpec.BooleanValue screenFlash;
        public final ForgeConfigSpec.IntValue detail;

        Client(ForgeConfigSpec.Builder builder) {
            builder.comment("What this machine draws").push("visuals");
            this.screenDistortion = builder.comment(new String[]{"The radial smear across the screen when the circle fires.", "This one copies the framebuffer and runs a shader over it. If another", "mod owns the pipeline -- Optifine, Iris, a shaderpack -- turn it off."}).define("screenDistortion", true);
            this.screenFlash = builder.comment("The white wash over the screen at the moment of firing.").define("screenFlash", true);
            this.detail = builder.comment(new String[]{"How finely the circles are tessellated.", "2 is what the spell was drawn for; 1 halves the segment counts;", "0 draws the rings and the beam and skips the ornament."}).defineInRange("detail", 2, 0, 2);
            builder.pop();
        }
    }
}

